 "content": "from collections import deque


def transform(grid):
    """Match the lower color-1 stencil to its duplicate above the divider;
    move the other upper object directly above the stencil, and remove the
    upper panel and divider (retaining the lower 9-row panel).
    """
    h, w = len(grid), len(grid[0])
    divider = next(r for r, row in enumerate(grid) if row and all(v == 5 for v in row))
    # Identify the connected non-background objects in the top panel.
    colors = {v for row in grid[:divider] for v in row if v not in (0, 5)}
    objs = {}
    for color in colors:
        cells = [(r, c) for r in range(divider) for c in range(w) if grid[r][c] == color]
        if cells:
            r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
            c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
            objs[color] = (r0, c0, [[int(grid[r][c] == color) for c in range(c0, c1 + 1)]
                                      for r in range(r0, r1 + 1)])
    # The lower stencil is color 1; select the upper object that is not its
    # identical shape, then place it centered horizontally on the stencil.
    lower = [(r, c) for r in range(divider + 1, h) for c in range(w) if grid[r][c] == 1]
    lr0, lr1 = min(r for r, c in lower), max(r for r, c in lower)
    lc0, lc1 = min(c for r, c in lower), max(c for r, c in lower)
    stencil = [[int(grid[r][c] == 1) for c in range(lc0, lc1 + 1)] for r in range(lr0, lr1 + 1)]
    chosen = None
    for color, (_, _, shape) in objs.items():
        if shape != stencil:
            chosen = (color, shape)
            break
    if chosen is None:
        raise ValueError('No nonmatching upper object')
    color, shape = chosen
    out = [row[:] for row in grid[divider + 1:]]
    # Drop selected shape so its bottom edge touches the stencil's top edge.
    sh, sw = len(shape), len(shape[0])
    top = lr0 - (divider + 1) - sh
    left = lc0 + (lc1 - lc0 + 1 - sw) // 2
    for r in range(sh):
        for c in range(sw):
            if shape[r][c]:
                out[top + r][left + c] = color
    return out
